INSERT INTO `mmd_blog_post` (`title`, `url_key`, `excerpt`, `content`, `author`, `status`, `published_at`, `related_skus`, `meta_title`, `meta_description`, `meta_keywords`, `created_at`, `updated_at`) SELECT 'Red Beacon Claude Code Training, Batch 2: A Finance Website Built From Scratch', 'red-beacon-claude-code-training-batch-2', 'In the second Claude Code cohort for Red Beacon, the team built and deployed a complete financial-consultancy website in a day — and we covered Claude Cowork too. Here is how, and how to run it for your team with WSQ funding.', '<h2>Round two with Red Beacon — going further</h2><p>After a strong first cohort, Red Beacon Asset Management sent a second batch of staff for more Claude Code. This time the team went beyond a single landing page and <strong>built a complete financial-consultancy website from scratch — live, in a day</strong>.</p><h2>What the team built: FinanceGuru, deployed in a day</h2><p>The cohort designed and shipped <a href="https://alfredang.github.io/financeconsultancy/" target="_blank" rel="noopener">FinanceGuru</a>, a full investment-advisory website, with Claude Code as the pair programmer. It includes:</p><ul><li>A hero section built around long-term wealth building</li><li>A "Why Us" grid of service pillars and a four-step advisory process</li><li>Client testimonials with ratings</li><li>A <strong>lead-magnet checklist download</strong> and clear consultation CTAs</li><li>An FAQ and a working enquiry form capturing name, email, goals and asset range</li></ul><p>Everyone left with a deployed site on a public URL — not a slide deck. The same curriculum is our public <a href="{{store direct_url=''wsq-agentic-ai-applications-with-claude-code.html''}}">WSQ Agentic AI Applications with Claude Code course</a>.</p><h2>The agentic mechanics behind it</h2><p>Building a full site meant putting the core Claude Code mechanics to work end to end:</p><ul><li><strong>Custom commands</strong> — reusable Markdown prompts for consistent section-building</li><li><strong>MCP tools</strong> — so the agent could test and validate in a real browser, not just suggest</li><li><strong>Skills</strong> — encoding brand voice and finance-appropriate, compliant copy</li><li><strong>Hooks &amp; sub-agents</strong> — automating checks and specialist review as the site grew</li></ul><h2>We also covered Claude Cowork</h2><p>Some Red Beacon staff already use <strong>Claude Cowork</strong> for collaborative, day-to-day AI work, so we covered how it complements Claude Code: use <em>Cowork</em> for team collaboration and shared context, and <em>Claude Code</em> for building and shipping software. Together they cover both the everyday-AI and the build-it workflows a modern team needs.</p><h2>Bring this to your team</h2><p>Run it as a public WSQ class or an on-site corporate cohort built around your own site or tools. As a <strong>WSQ-accredited course</strong> it attracts <strong>up to 70% funding</strong> for eligible Singaporeans and PRs, staff can apply <strong>SkillsFuture Credit</strong>, and companies stack <strong>SkillsFuture Enterprise Credit (SFEC)</strong> plus absentee payroll support. <a href="{{store direct_url=''wsq-agentic-ai-applications-with-claude-code.html''}}">View class dates and register here</a>.</p><h2>FAQ</h2><h3>Can a non-technical team really build a whole website?</h3><p>Yes — the Red Beacon cohort were finance and operations professionals. You describe intent in English and Claude Code builds, tests and ships it with you.</p><h3>How does Claude Cowork fit in?</h3><p>Cowork is for collaborative, everyday AI work across a team; Claude Code is for building and deploying software. We show how to use both together.</p><h3>Is the course funded?</h3><p>Yes — WSQ funding up to 70%, SkillsFuture Credit for individuals, and SFEC for company-sponsored staff.</p><h2>What to do next</h2><ol><li>Pick a real site or internal tool your team needs</li><li>Reserve seats in the <a href="{{store direct_url=''wsq-agentic-ai-applications-with-claude-code.html''}}"><strong>WSQ Agentic AI Applications with Claude Code</strong></a> class, or ask about an on-site cohort like Red Beacon''s</li><li>Leave with a deployed website and a reusable agentic toolkit</li></ol>', 'Tertiary Infotech Academy', 1, '2026-06-29', 'TGS-2025052468', 'Claude Code Training Batch 2 (Red Beacon) | WSQ Funded', 'Red Beacon''s 2nd Claude Code cohort built a full finance website in a day and covered Claude Cowork. Run it for your team with up to 70% WSQ funding.', 'claude code, claude cowork, agentic ai, corporate training, red beacon, wsq funding, skillsfuture', NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `mmd_blog_post` WHERE `url_key` = 'red-beacon-claude-code-training-batch-2');

-- New tag + reuse existing
INSERT INTO `tag` (`name`, `status`) SELECT * FROM (SELECT 'Claude Cowork' AS n, 1 AS s) t WHERE NOT EXISTS (SELECT 1 FROM `tag` WHERE `name` = 'Claude Cowork');

INSERT IGNORE INTO `mmd_blog_post_tag` (`post_id`, `tag_id`) SELECT p.`post_id`, t.`tag_id` FROM `mmd_blog_post` p JOIN `tag` t ON t.`name` IN ('Claude Code','Claude Cowork','Agentic AI','Corporate Training') WHERE p.`url_key` = 'red-beacon-claude-code-training-batch-2';

